{
  "vulnerable_symbols": [
    "axios.request",
    "axios.get",
    "axios.post"
  ],
  "trigger": "在浏览器中发起 axios 请求，且 xsrfCookieName 被攻击者控制为含正则元字符的恶意值，导致 document.cookie 匹配时 ReDoS。",
  "preconditions": [
    "运行在标准浏览器环境（存在 document.cookie，非 Node HTTP adapter、React Native 或 web worker）",
    "攻击者可控数据能进入 xsrfCookieName 配置或 unsafe cookie helper",
    "请求未设置 xsrfCookieName: null"
  ],
  "exploit_evidence": [
    {
      "src": 3,
      "kind": "poc",
      "quote": "Exploitation Public or AI PoC available; prioritize validation"
    }
  ],
  "fixed_version": "1.16.0",
  "summary_zh": "axios 浏览器端用未转义 XSRF cookie 名构造正则，外部可控可致 ReDoS，升级 1.16.0 并限制该配置。"
}
